                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.ENLM = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
